/*
 * A103280  Array read by antidiagonals, generated by the matrix M =
 *          [1,1,1;1,N,1;1,1,1].
 * https://oeis.org/A103280
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabl, easy
 * Formula:   a(n) is read by antidiagonals from the matrix * M =
 *            [1,1,1;1,N,1;1,1,1] * where T(N,1)=1, T(N,2)=N+2, and for k≥3 *
 *            T(N,k) = (N+2)*T(N,k-1) - (2N-2)*T(N,k-2). * The sequence a(n)
 *            is the list of T(N,k) where N and k are obtained * by
 *            transforming the 1‑based index n into diagonal “d” and offset
 *            *...
 * Range:     u8 n <= 26, u16 n <= 62, u32 n <= 62, u64 n <= 62, u128 n <= 62,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

static seq_t compute_T(idx_t N, idx_t k)
{
    if (k == 1) return (seq_t)1;
    if (k == 2) return (seq_t)(N + 2);

    seq_t prev2 = (seq_t)1;                 /* T(N,1)   */
    seq_t prev1 = (seq_t)(N + 2);           /* T(N,2)   */
    seq_t cur;

    /* Use 128‑bit intermediates when seq_t fits in 8 bytes */
    if (sizeof(seq_t) <= 8) {
        unsigned __int128 coeff1 = (unsigned __int128)(N + 2);
        for (idx_t i = 3; i <= k; ++i) {
            unsigned __int128 prod1 = coeff1 * (unsigned __int128)prev1;
            unsigned __int128 temp;
            if (N == 0) {
                temp = prod1 + (unsigned __int128)2 * (unsigned __int128)prev2;
            } else if (N == 1) {
                temp = prod1;                 /* coeff2 is zero */
            } else {
                unsigned __int128 coeff2 = (unsigned __int128)(2 * N - 2);
                temp = prod1 - coeff2 * (unsigned __int128)prev2;
            }
            cur = (seq_t)temp;
            prev2 = prev1;
            prev1 = cur;
        }
        return prev1;
    } else {
        /* seq_t is large enough or arbitrary‑precision */
        seq_t coeff1 = (seq_t)(N + 2);
        for (idx_t i = 3; i <= k; ++i) {
            seq_t temp = coeff1 * prev1;
            if (N == 0) {
                temp += (seq_t)2 * prev2;
            } else if (N > 1) {
                seq_t coeff2 = (seq_t)(2 * N - 2);
                temp -= coeff2 * prev2;
            }
            cur = temp;
            prev2 = prev1;
            prev1 = cur;
        }
        return prev1;
    }
}

seq_t a(idx_t n)
{
    /* Find diagonal d such that (d+1)*(d+2)/2 > n */
    idx_t d = 0;
    while ((d + 1) * (d + 2) / 2 <= n)
        ++d;

    /* Triangular number of d */
    idx_t tri = d * (d + 1) / 2;
    idx_t offset = n - tri;          /* 0‑based offset within diagonal */
    idx_t N = d - offset;            /* row index (0‑based) */
    idx_t k = offset + 1;            /* column index, 1‑based */

    return compute_T(N, k);
}
